/**
 * A REAL agentfootprint 19 recording (generated by `fixtures/generate.ts`):
 * one turn filed in the parts layout (index format 2, sub-flow payloads with
 * their invocations) and in the whole layout. The viewer reads the parts
 * recording through the same lazy source a host serves — the root from
 * `readRoot()`, each child reply from `readInvocation()` as is — and, once the
 * payloads are read, every view says what the whole recording says.
 */
import React from 'react';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { gunzipSync } from 'node:zlib';
import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import type { StepGraph, StepNode } from 'agentfootprint/observe';
import { toVisualizationSnapshots } from 'footprint-explainable-ui';
import {
  projectRecordingSource, readRecordingSourceRoot, readRecordingSubflow, type RecordedInvocation, type RecordedSubflowReply,
} from '../../src/core/recordingSourceCodec/index.js';
import { readPayloadMarks } from '../../src/core/subflowPayloads/index.js';
import { buildLLMText } from '../../src/core/copyForLLM.js';
import { cursorProvenance } from '../../src/core/cursorProvenance.js';
import { noBookmarkStore } from '../../src/core/bookmarks/index.js';
import { NodeDetailPanel } from '../../src/react/NodeDetailPanel.js';
import { Lens } from '../../src/react/Lens.js';
import { useSharedCursor } from '../../src/react/useSharedCursor.js';
import { createLensRecordingSource } from '../../src/react/recordingSource/controller.js';
import { useStepPayloads } from '../../src/react/recordingSource/useStepPayloads.js';

type Json = Record<string, any>;
const fixture = JSON.parse(gunzipSync(readFileSync(join(dirname(fileURLToPath(import.meta.url)), 'fixtures/saved-turn-19.json.gz'))).toString('utf8')) as {
  agentfootprint: string;
  parts: { index: Json; snapshotRunId?: string; invocations: { key: string; path: string[]; subflowId: string }[]; root: Json; replies: Record<string, RecordedSubflowReply> };
  whole: Json;
};

/** The two sources a host would serve: the parts recording as read back, and the whole recording projected. */
function sources() {
  const { parts, whole } = fixture;
  const dto = { schema: 'agentfootprint-lens.recording-source/v1', recording: parts.root,
    invocations: parts.invocations.map(item => ({ invocationPath: item.path, mountRuntimeStageId: item.key, subflowId: item.subflowId,
      ...(parts.snapshotRunId !== undefined && { runId: parts.snapshotRunId }) })) };
  const admitted = readRecordingSourceRoot(dto);
  if (admitted.status !== 'ready') throw new Error(`The real 19 root was refused: ${admitted.reason}`);
  const partsRead = vi.fn(async (request: RecordedInvocation) => parts.replies[request.mountRuntimeStageId]!);
  const partsSource = createLensRecordingSource({ root: admitted.value, loadSubflow: partsRead });
  const projected = projectRecordingSource(whole);
  if (projected.status !== 'ready') throw new Error(`The whole recording was refused: ${projected.reason}`);
  const wholeRead = vi.fn(async (request: RecordedInvocation) => {
    const read = readRecordingSubflow(whole, request);
    if (read.status !== 'ready') throw new Error(read.reason);
    return read.value;
  });
  const wholeSource = createLensRecordingSource({ root: projected.value, loadSubflow: wholeRead });
  return { partsSource, partsRead, wholeSource, wholeRead };
}
const graphOf = (source: { observed: { runner: unknown } }) =>
  (source.observed.runner as { enable: { flowchart(): { getSnapshot(): StepGraph } } }).enable.flowchart().getSnapshot();
function Detail({ source, related, node }: { source: ReturnType<typeof createLensRecordingSource>; related?: readonly StepNode[]; node?: StepNode }) {
  const payloads = useStepPayloads(source, undefined);
  return <NodeDetailPanel {...(node ? { node } : { relatedNodes: related!, cursorRuntimeStageId: '__root__#0', rootPhase: 'end' as const })}
    payloads={payloads.reader} onNeedPayloads={payloads.request} />;
}

describe(`a real agentfootprint ${fixture.agentfootprint} recording, saved in parts and whole`, () => {
  it('is index format 2 with every sub-flow payload moved, marked in the base and carried by each child reply', () => {
    const { parts, whole } = fixture;
    expect(parts.index.format).toBe('agentfootprint.recording.index.v2');
    expect(parts.index.subflowPayloads.rows).toEqual([0]);
    const marks = readPayloadMarks(parts.root.snapshot);
    expect(marks.size).toBe(parts.invocations.length);
    expect(readPayloadMarks(whole.snapshot).size).toBe(0);
    for (const invocation of parts.invocations) {
      const reply = parts.replies[invocation.key]!;
      expect(Object.keys(reply.payloads ?? {}).sort()).toEqual(
        [marks.get(invocation.key)!.entry && 'entry', marks.get(invocation.key)!.exit && 'exit'].filter(Boolean).sort());
    }
  });

  it('shows the same related cards from the parts recording, once its payloads are read, as from the whole one', async () => {
    const { partsSource, partsRead, wholeSource, wholeRead } = sources();
    try {
      const wholeGraph = graphOf(wholeSource), partsGraph = graphOf(partsSource);
      expect(partsGraph.nodes.map(node => node.id)).toEqual(wholeGraph.nodes.map(node => node.id));
      const calls = partsGraph.nodes.filter(node => node.slotBoundaries?.messages);
      expect(calls).toHaveLength(2);
      const wholeShown = render(<Detail source={wholeSource} related={wholeGraph.nodes} />);
      const wholeText = wholeShown.container.innerHTML; wholeShown.unmount();
      expect(wholeText).toContain('Messages (composed)');
      expect(wholeRead).not.toHaveBeenCalled();
      const shown = render(<Detail source={partsSource} related={partsGraph.nodes} />);
      expect(screen.getAllByText(/It is stored with its sub-flow invocation/).length).toBeGreaterThan(0);
      await waitFor(() => expect(partsRead).toHaveBeenCalledTimes(calls.length * 3));
      await waitFor(() => expect(shown.container.innerHTML).toBe(wholeText));
      // Read through the host's own child read, never the renderer's loaded children.
      expect(partsSource.getSnapshot().loads).toEqual([]);
      for (const node of partsGraph.nodes) {
        const step = render(<Detail source={partsSource} node={node} />);
        const want = render(<Detail source={wholeSource} node={wholeGraph.nodes.find(other => other.id === node.id)!} />);
        expect(step.container.innerHTML).toBe(want.container.innerHTML);
        step.unmount(); want.unmount();
      }
      shown.unmount();
    } finally { partsSource.dispose(); wholeSource.dispose(); }
  });

  it('copies the same text for an LLM from either recording, and drills into a child of each', async () => {
    const { partsSource, wholeSource } = sources();
    try {
      for (const request of partsSource.getSnapshot().invocations) await partsSource.loadPayloads!(request);
      const reader = (source: typeof partsSource) => {
        let out!: ReturnType<typeof useStepPayloads>;
        function Probe() { out = useStepPayloads(source, undefined); return null; }
        render(<Probe />);
        return out.reader;
      };
      const text = (source: typeof partsSource) => buildLLMText({ recorder: source.observed.recorder, stepGraph: graphOf(source), payloads: reader(source) });
      expect(text(partsSource)).toBe(text(wholeSource));
      expect(buildLLMText({ recorder: partsSource.observed.recorder, stepGraph: graphOf(partsSource) }))
        .toBe(buildLLMText({ recorder: wholeSource.observed.recorder, stepGraph: graphOf(wholeSource) }));
      const request = partsSource.getSnapshot().invocations[0]!;
      await partsSource.load(request);
      await wholeSource.load(wholeSource.getSnapshot().invocations[0]!);
      expect(partsSource.getSnapshot().loads.map(load => load.status)).toEqual(['ready']);
      expect(wholeSource.getSnapshot().loads.map(load => load.status)).toEqual(['ready']);
      expect(partsSource.getAxis(request.invocationPath)).toEqual(wholeSource.getAxis(request.invocationPath));
    } finally { partsSource.dispose(); wholeSource.dispose(); }
  });

  it('renders the Lens at the run’s end the same from either recording once the payloads are read', async () => {
    const { partsSource, wholeSource } = sources();
    const lensAt = async (source: typeof partsSource) => {
      function Host() {
        const shared = useSharedCursor(source.observed.recorder);
        return <Lens recorder={source.observed.recorder} runner={source.observed.runner} recordingSource={source}
          shared={shared} granularity="group" bookmarkStore={noBookmarkStore()} />;
      }
      const mounted = render(<Host />);
      fireEvent.click(screen.getByRole('button', { name: 'Jump to latest' }));
      await waitFor(() => expect(screen.getAllByText('Messages (composed)')).toHaveLength(2));
      await waitFor(() => expect(screen.queryAllByText(/It is stored with its sub-flow invocation/)).toEqual([]));
      const region = screen.getByText('All steps in this scope').parentElement!.textContent;
      mounted.unmount();
      return region;
    };
    try {
      expect(await lensAt(partsSource)).toBe(await lensAt(wholeSource));
    } finally { partsSource.dispose(); wholeSource.dispose(); }
  });

  it('holds write markers in its trees (writeTracking: summary); no view shows a marker as a value', () => {
    const isMarker = (value: unknown) => typeof value === 'object' && value !== null && (value as Json).__writeSummary === true;
    const markersIn = (tree: Json) => {
      let count = 0;
      const pending: unknown[] = [tree];
      while (pending.length) {
        const stage = pending.pop() as Json | undefined;
        if (!stage) continue;
        count += Object.values(stage.stageWrites ?? {}).filter(isMarker).length;
        pending.push(...(stage.children ?? []), stage.next);
      }
      return count;
    };
    const deepMarker = (value: unknown): boolean => isMarker(value)
      || (typeof value === 'object' && value !== null && Object.values(value).some(deepMarker));
    const { whole, parts } = fixture;
    expect(markersIn(whole.snapshot.executionTree)).toBeGreaterThan(0);
    // explainable-ui's flattener reads a stage's memory from its commit bundle, never from the markers.
    const stages = toVisualizationSnapshots(whole.snapshot as never);
    expect(stages.length).toBeGreaterThan(0);
    expect(stages.some(stage => deepMarker(stage.memory))).toBe(false);
    // The check can fail: without its commit bundles a stage's memory would be read from the markers.
    const bare = { ...whole.snapshot, commitLog: [] };
    expect(toVisualizationSnapshots(bare as never).some(stage => deepMarker(stage.memory))).toBe(true);
    expect(stages.filter(stage => /Wrote: /.test(stage.narrative ?? '')).every(stage => !/\[object Object\]/.test(stage.narrative!))).toBe(true);
    for (const reply of Object.values(parts.replies)) {
      const context = (reply.result as Json).treeContext;
      expect(markersIn(context.stageContexts)).toBeGreaterThan(0);
      const child = toVisualizationSnapshots({ executionTree: context.stageContexts, commitLog: context.history, sharedState: context.globalContext } as never);
      expect(child.some(stage => deepMarker(stage.memory))).toBe(false);
    }
    // The cursor's provenance reads written keys from the commit log, so a write that happened is listed.
    const observed = createLensRecordingSource({ root: projectRecordingSource(whole).status === 'ready' ? (projectRecordingSource(whole) as { value: unknown }).value : null,
      loadSubflow: async () => ({ result: null }) });
    try {
      const log = whole.snapshot.commitLog as { runtimeStageId: string; trace: { path: string }[] }[];
      const writer = log.find(commit => commit.trace.length > 0)!;
      const provenance = cursorProvenance(observed.observed.runner, writer.runtimeStageId);
      expect(provenance?.writtenKeys.length).toBeGreaterThan(0);
      expect(provenance!.writtenKeys.every(key => typeof key === 'string')).toBe(true);
    } finally { observed.dispose(); }
  });
});
